#include <bits/stdc++.h>
using namespace std;

const int LOG = 20;                   // 2^20 > 10^6 — wystarczy dla n <= 10^6
int n;
vector<vector<int>> g, up;            // up[k][v] = przodek v o 2^k poziomów wyżej
vector<int> dep;

int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    int diff = dep[a] - dep[b];
    for (int k = 0; k < LOG; k++)
        if (diff >> k & 1) a = up[k][a];          // wyrównanie głębokości
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; k--)
        if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
    return up[0][a];                               // a, b to dzieci LCA
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> n >> q;
    g.assign(n + 1, {});
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    up.assign(LOG, vector<int>(n + 1, 1));        // przodek korzenia = korzeń (skoki nie wychodzą poza drzewo)
    dep.assign(n + 1, 0);
    vector<bool> vis(n + 1, false);
    queue<int> qu;                                 // BFS zamiast rekurencji: bezpieczne dla n = 10^6
    qu.push(1); vis[1] = true;
    while (!qu.empty()) {
        int v = qu.front(); qu.pop();
        for (int u : g[v]) if (!vis[u]) {
            vis[u] = true;
            up[0][u] = v;
            dep[u] = dep[v] + 1;
            qu.push(u);
        }
    }
    for (int k = 1; k < LOG; k++)
        for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
    while (q--) {
        int a, b;
        cin >> a >> b;
        cout << lca(a, b) << '\n';
    }
}

const int LOG = 20;
vector<vector<int>> up;     // jak w programie wyżej
vector<int> dep;
// k-ty przodek v (k = 0 -> v); -1 gdy k > głębokość
int kthAncestor(int v, int k) {
    if (k > dep[v]) return -1;
    for (int j = 0; j < LOG; j++)
        if (k >> j & 1) v = up[j][v];
    return v;
}

