#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    // Iteracyjny pełny Euler tour
    vector<int> euler, first(n + 1), dep(n + 1, 0), par(n + 1, 0), it(n + 1, 0), st = {1};
    euler.reserve(2 * n);
    first[1] = 0;
    euler.push_back(1);
    while (!st.empty()) {
        int v = st.back();
        if (it[v] < (int)g[v].size()) {
            int u = g[v][it[v]++];
            if (u == par[v]) continue;
            par[u] = v;
            dep[u] = dep[v] + 1;
            first[u] = euler.size();
            euler.push_back(u);                    // wejście do u
            st.push_back(u);
        } else {
            st.pop_back();
            if (!st.empty()) euler.push_back(st.back());   // powrót do rodzica
        }
    }
    int m = euler.size();                          // 2n - 1
    int K = __lg(m) + 1;
    auto lepszy = [&](int a, int b) { return dep[a] < dep[b] ? a : b; };
    vector<vector<int>> sp(K, vector<int>(m));
    sp[0] = euler;
    for (int k = 1; k < K; k++)
        for (int i = 0; i + (1 << k) <= m; i++)
            sp[k][i] = lepszy(sp[k - 1][i], sp[k - 1][i + (1 << (k - 1))]);
    auto lca = [&](int u, int v) {
        int l = first[u], r = first[v];
        if (l > r) swap(l, r);
        int k = __lg(r - l + 1);
        return lepszy(sp[k][l], sp[k][r - (1 << k) + 1]);
    };
    while (q--) {
        int u, v;
        cin >> u >> v;
        cout << lca(u, v) << '\n';
    }
}

