#include <bits/stdc++.h>
using namespace std;

// k-ty wierzchołek na ścieżce u -> v (k = 0 to u); -1 gdy ścieżka krótsza
const int LOG = 18;
int n;
vector<vector<int>> g, up;
vector<int> dep;

int kth(int v, int k) { for (int j = 0; j < LOG; j++) if (k >> j & 1) v = up[j][v]; return v; }
int lca(int a, int b) {
    if (dep[a] < dep[b]) swap(a, b);
    a = kth(a, dep[a] - dep[b]);
    if (a == b) return a;
    for (int k = LOG - 1; k >= 0; k--) if (up[k][a] != up[k][b]) { a = up[k][a]; b = up[k][b]; }
    return up[0][a];
}
int kthOnPath(int u, int v, int k) {
    int l = lca(u, v);
    int du = dep[u] - dep[l], dv = dep[v] - dep[l];
    if (k > du + dv) return -1;
    if (k <= du) return kth(u, k);           // jeszcze w drodze w górę
    return kth(v, du + dv - k);              // już w drodze w dół: liczymy od v
}

int main() {
    int q;
    cin >> n >> q;
    g.assign(n + 1, {});
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    up.assign(LOG, vector<int>(n + 1, 1));
    dep.assign(n + 1, 0);
    vector<int> order = {1};
    vector<bool> vis(n + 1, false);
    vis[1] = true;
    for (size_t i = 0; i < order.size(); i++) {
        int v = order[i];
        for (int u : g[v]) if (!vis[u]) { vis[u] = true; up[0][u] = v; dep[u] = dep[v] + 1; order.push_back(u); }
    }
    for (int k = 1; k < LOG; k++)
        for (int v = 1; v <= n; v++) up[k][v] = up[k - 1][up[k - 1][v]];
    while (q--) {
        int u, v, k;
        cin >> u >> v >> k;
        cout << kthOnPath(u, v, k) << '\n';
    }
}

