#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> par(n + 1, 0), order, st = {1};
    while (!st.empty()) {                       // kolejność: rodzic przed dziećmi
        int v = st.back(); st.pop_back();
        order.push_back(v);
        for (int u : g[v]) if (u != par[v]) { par[u] = v; st.push_back(u); }
    }
    vector<long long> misIn(n + 1), misOut(n + 1), vcIn(n + 1), vcOut(n + 1), cIn(n + 1), cOut(n + 1);
    for (int i = n - 1; i >= 0; i--) {            // od liści do korzenia
        int v = order[i];
        misIn[v] = 1; misOut[v] = 0;              // max zbiór niezależny
        vcIn[v] = 1;  vcOut[v] = 0;               // min pokrycie wierzchołkowe
        cIn[v] = 1;   cOut[v] = 1;                // liczba zbiorów niezależnych
        for (int c : g[v]) {
            if (c == par[v]) continue;
            misIn[v] += misOut[c];
            misOut[v] += max(misIn[c], misOut[c]);
            vcIn[v] += min(vcIn[c], vcOut[c]);
            vcOut[v] += vcIn[c];                  // v niewybrany -> każde dziecko musi być wybrane
            cIn[v] = cIn[v] * cOut[c] % MOD;
            cOut[v] = cOut[v] * ((cIn[c] + cOut[c]) % MOD) % MOD;
        }
    }
    cout << max(misIn[1], misOut[1]) << '\n';
    cout << min(vcIn[1], vcOut[1]) << '\n';
    cout << (cIn[1] + cOut[1]) % MOD << '\n';     // wliczając zbiór pusty
}

