    for (size_t i = 0; i < order.size(); i++)
        for (int u : g[order[i]]) if (!vis[u]) { vis[u] = true; par[u] = order[i]; order.push_back(u); }
    vector<long long> sz(n + 1, 1), down(n + 1, 0), ans(n + 1, 0);
    for (int i = n - 1; i > 0; i--) {             // przejście w dół (od liści)
        int v = order[i], p = par[v];
