#include <bits/stdc++.h>
using namespace std;

// Dla każdego v: liczba spójnych podzbiorów zawierających v, modulo M (M nie musi być pierwsze!).
// f(v) = Π (1 + f(sąsiad w kierunku od v)). Dzielenia modulo nie ma -> prefiksy i sufiksy po dzieciach.
int main() {
    int n;
    long long M;
    cin >> n >> M;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> par(n + 1, 0), order = {1};
    vector<bool> vis(n + 1, false);
    vis[1] = true;
    for (size_t i = 0; i < order.size(); i++)
        for (int u : g[order[i]]) if (!vis[u]) { vis[u] = true; par[u] = order[i]; order.push_back(u); }
    vector<vector<int>> ch(n + 1);
    for (int i = 1; i < n; i++) ch[par[order[i]]].push_back(order[i]);
    vector<long long> down(n + 1, 1), up(n + 1, 0), ans(n + 1);
    for (int i = n - 1; i >= 0; i--) {
        int v = order[i];
        for (int c : ch[v]) down[v] = down[v] * (1 + down[c]) % M;
    }
    for (int i = 0; i < n; i++) {
        int v = order[i];
        int k = ch[v].size();
        long long zGory = (v == 1) ? 1 : (1 + up[v]) % M;     // wkład strony rodzica
        ans[v] = down[v] * zGory % M;
        vector<long long> pre(k + 1, 1), suf(k + 1, 1);
        for (int j = 0; j < k; j++) pre[j + 1] = pre[j] * (1 + down[ch[v][j]]) % M;
        for (int j = k - 1; j >= 0; j--) suf[j] = suf[j + 1] * (1 + down[ch[v][j]]) % M;
        for (int j = 0; j < k; j++)                            // wszystko poza dzieckiem j
            up[ch[v][j]] = pre[j] * suf[j + 1] % M * zGory % M;
    }
    for (int v = 1; v <= n; v++) cout << ans[v] << '\n';
}

