    vector<int> col(n + 1);
    for (int i = 1; i <= n; i++) cin >> col[i];
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> par(n + 1, 0), order = {1};
    vector<bool> vis(n + 1, false);
    vis[1] = true;
    for (size_t i = 0; i < order.size(); i++)
        for (int u : g[order[i]]) if (!vis[u]) { vis[u] = true; par[u] = order[i]; order.push_back(u); }

    vector<set<int>> S(n + 1);
    vector<int> ans(n + 1);
    for (int i = n - 1; i >= 0; i--) {            // dzieci przed rodzicem
        int v = order[i];
        S[v].insert(col[v]);                      // S[v] zawiera już scalone zbiory dzieci
        ans[v] = S[v].size();
        if (v == 1) break;
        int p = par[v];
        if (S[p].size() < S[v].size()) swap(S[p], S[v]);   // O(1): zamiana wnętrz
        for (int x : S[v]) S[p].insert(x);       // mniejszy do większego
        S[v].clear();
    }
    for (int v = 1; v <= n; v++) cout << ans[v] << (v == n ? '\n' : ' ');
}

#include <bits/stdc++.h>
using namespace std;

// Sack (DSU on tree): tablica liczników cnt[kolor], O(n log n), bez set-ów.
const int MAXN = 200005;
int n, col[MAXN], sz[MAXN], big[MAXN], tin[MAXN], tout[MAXN], ver[MAXN], timer_ = 0;
int cnt[MAXN], distinct_ = 0, ans[MAXN];
vector<int> g[MAXN];

void prep(int v, int p) {                 // rozmiary, ciężkie dziecko, kolejność Eulera
    sz[v] = 1; big[v] = 0;
    tin[v] = ++timer_; ver[timer_] = v;
    for (int u : g[v]) if (u != p) {
        prep(u, v);
        sz[v] += sz[u];
        if (!big[v] || sz[u] > sz[big[v]]) big[v] = u;
    }
    tout[v] = timer_;
}
void addV(int v, int d) {
    if (d > 0 && cnt[col[v]]++ == 0) distinct_++;
    if (d < 0 && --cnt[col[v]] == 0) distinct_--;
}
void sack(int v, int p, bool keep) {
    for (int u : g[v]) if (u != p && u != big[v]) sack(u, v, false);   // lekkie: policz i wyczyść
    if (big[v]) sack(big[v], v, true);                                  // ciężkie: zostaw liczniki
    for (int u : g[v]) if (u != p && u != big[v])
        for (int t = tin[u]; t <= tout[u]; t++) addV(ver[t], +1);       // dołóż lekkie poddrzewa
    addV(v, +1);
    ans[v] = distinct_;
    if (!keep)
        for (int t = tin[v]; t <= tout[v]; t++) addV(ver[t], -1);
}

int main() {
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> col[i];
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    prep(1, 0);
    sack(1, 0, true);
    for (int v = 1; v <= n; v++) cout << ans[v] << (v == n ? '\n' : ' ');
}

