#include <bits/stdc++.h>
using namespace std;

// Centroid(y) drzewa: wierzchołki, dla których największy kawałek po usunięciu ma <= n/2
int main() {
    int n;
    cin >> n;
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> par(n + 1, 0), order = {1}, sz(n + 1, 1);
    vector<bool> vis(n + 1, false);
    vis[1] = true;
    for (size_t i = 0; i < order.size(); i++)
        for (int u : g[order[i]]) if (!vis[u]) { vis[u] = true; par[u] = order[i]; order.push_back(u); }
    for (int i = n - 1; i > 0; i--) sz[par[order[i]]] += sz[order[i]];
    for (int v = 1; v <= n; v++) {
        int najw = n - sz[v];                     // kawałek „nad” v
        for (int u : g[v]) if (u != par[v]) najw = max(najw, sz[u]);
        if (2 * najw <= n) cout << v << ' ';
    }
    cout << '\n';
}

#include <bits/stdc++.h>
using namespace std;

// Liczba par wierzchołków w odległości dokładnie K — dekompozycja centroidowa, O(n log n)
int n, K;
vector<vector<int>> g;
vector<bool> removed;
vector<int> sz, par_;
vector<long long> cnt;                    // cnt[d] = ile wierzchołków w odległości d od centroidu (już przetworzone)
long long wynik = 0;

int znajdzCentroid(int root) {
    vector<int> order = {root};
    par_[root] = 0;
    for (size_t i = 0; i < order.size(); i++)
        for (int u : g[order[i]]) if (!removed[u] && u != par_[order[i]]) { par_[u] = order[i]; order.push_back(u); }
    int total = order.size();
    for (int i = total - 1; i >= 0; i--) {
        int v = order[i];
        sz[v] = 1;
        for (int u : g[v]) if (!removed[u] && u != par_[v]) sz[v] += sz[u];
    }
    for (int v : order) {
        int najw = total - sz[v];
        for (int u : g[v]) if (!removed[u] && u != par_[v]) najw = max(najw, sz[u]);
        if (2 * najw <= total) return v;
    }
    return root;
}

int main() {
    cin >> n >> K;
    g.assign(n + 1, {});
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    removed.assign(n + 1, false);
    sz.assign(n + 1, 0);
    par_.assign(n + 1, 0);
    cnt.assign(K + 1, 0);
    vector<int> doZrobienia = {1};             // korzenie kawałków (zamiast rekurencji)
    while (!doZrobienia.empty()) {
        int r = doZrobienia.back(); doZrobienia.pop_back();
        int c = znajdzCentroid(r);
        removed[c] = true;
        cnt[0] = 1;                            // sam centroid
        int maxd = 0;
        for (int s : g[c]) {
            if (removed[s]) continue;
            vector<int> glebokosci;
            vector<array<int, 3>> q = {{s, c, 1}};   // (wierzchołek, rodzic, odległość od c)
            for (size_t i = 0; i < q.size(); i++) {
                auto [v, p, d] = q[i];
                if (d > K) continue;
                glebokosci.push_back(d);
                for (int u : g[v]) if (u != p && !removed[u]) q.push_back({u, v, d + 1});
            }
            for (int d : glebokosci) wynik += cnt[K - d];      // pary z wcześniejszymi poddrzewami
            for (int d : glebokosci) { cnt[d]++; maxd = max(maxd, d); }
        }
        fill(cnt.begin(), cnt.begin() + maxd + 1, 0);
        for (int s : g[c]) if (!removed[s]) doZrobienia.push_back(s);
    }
    cout << wynik << '\n';
}

qa.a:
Centroid to wierzchołek, którego usunięcie zostawia kawałki o rozmiarze ≤ n/2. Policz `sz[]` od korzenia;
dla `v` największy kawałek to `max(n − sz[v], max sz[dziecko])` — centroid to `v` z wartością ≤ n/2. O(n).
Zawsze istnieje: idź od korzenia do dziecka z `sz > n/2`, dopóki takie jest — w końcu staniesz w centroidzie.

