int centroid(int root) {
    vector<int> ord = {root};
    par_[root] = 0;
    for (size_t i = 0; i < ord.size(); i++)
        for (int u : g[ord[i]]) if (!removed[u] && u != par_[ord[i]]) { par_[u] = ord[i]; ord.push_back(u); }
