#include <bits/stdc++.h>
using namespace std;

int n, N;
vector<long long> tsum, tmax;            // drzewo przedziałowe bottom-up: suma i max

void ustaw(int i, long long x) {
    i += N;
    tsum[i] = tmax[i] = x;
    for (i >>= 1; i; i >>= 1) {
        tsum[i] = tsum[2 * i] + tsum[2 * i + 1];
        tmax[i] = max(tmax[2 * i], tmax[2 * i + 1]);
    }
}
pair<long long, long long> zapytaj(int l, int r) {     // [l, r] -> (suma, max)
    long long s = 0, m = LLONG_MIN;
    for (l += N, r += N + 1; l < r; l >>= 1, r >>= 1) {
        if (l & 1) { s += tsum[l]; m = max(m, tmax[l]); l++; }
        if (r & 1) { --r; s += tsum[r]; m = max(m, tmax[r]); }
    }
    return {s, m};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int q;
    cin >> n >> q;
    vector<long long> val(n + 1);
    for (int i = 1; i <= n; i++) cin >> val[i];
    vector<vector<int>> g(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    // 1) BFS: rodzic, głębokość; rozmiary i ciężkie dzieci od liści
    vector<int> par(n + 1, 0), dep(n + 1, 0), sz(n + 1, 1), heavy(n + 1, 0), order = {1};
    vector<bool> vis(n + 1, false);
    vis[1] = true;
    for (size_t i = 0; i < order.size(); i++)
        for (int u : g[order[i]]) if (!vis[u]) {
            vis[u] = true; par[u] = order[i]; dep[u] = dep[order[i]] + 1; order.push_back(u);
        }
    for (int i = n - 1; i > 0; i--) {
        int v = order[i], p = par[v];
        sz[p] += sz[v];
    }
    for (int i = n - 1; i > 0; i--) {
        int v = order[i], p = par[v];
        if (!heavy[p] || sz[v] > sz[heavy[p]]) heavy[p] = v;
    }
    // 2) łańcuchy: każdy wierzchołek, który nie jest ciężkim dzieckiem, zaczyna nowy łańcuch
    vector<int> head(n + 1), pos(n + 1);
    int cur = 0;
    for (int v : order) {
        if (v != 1 && heavy[par[v]] == v) continue;
        for (int x = v; x; x = heavy[x]) { head[x] = v; pos[x] = cur++; }
    }
    N = 1;
    while (N < n) N <<= 1;
    tsum.assign(2 * N, 0);
    tmax.assign(2 * N, LLONG_MIN);
    for (int v = 1; v <= n; v++) ustaw(pos[v], val[v]);

    auto sciezka = [&](int u, int v) {                // (suma, max) na ścieżce u–v
        long long s = 0, m = LLONG_MIN;
        while (head[u] != head[v]) {
            if (dep[head[u]] < dep[head[v]]) swap(u, v);
            auto [a, b] = zapytaj(pos[head[u]], pos[u]);
            s += a; m = max(m, b);
            u = par[head[u]];
        }
        if (dep[u] > dep[v]) swap(u, v);
        auto [a, b] = zapytaj(pos[u], pos[v]);       // u = LCA
        return make_pair(s + a, max(m, b));
    };
    while (q--) {
        int t, a, b;
        cin >> t >> a >> b;
        if (t == 1) ustaw(pos[a], b);                 // 1 v x : wartość v := x
        else if (t == 2) cout << sciezka(a, b).first << '\n';    // 2 u v : suma na ścieżce
        else cout << sciezka(a, b).second << '\n';               // 3 u v : max na ścieżce
    }
}

// Wersja rekurencyjna z numeracją „ciężkie dziecko pierwsze”: wtedy KAŻDE poddrzewo też jest przedziałem
// [pos[v], pos[v] + sz[v] - 1], więc ta sama struktura obsłuży zapytania o ścieżki i o poddrzewa.
const int MAXN = 200005;
vector<int> g[MAXN];
int par_[MAXN], dep_[MAXN], sz_[MAXN], heavy_[MAXN], head_[MAXN], pos_[MAXN], cur_ = 0;

void dfsSz(int v, int p) {
    par_[v] = p; sz_[v] = 1; heavy_[v] = 0;
    for (int u : g[v]) if (u != p) {
        dep_[u] = dep_[v] + 1;
        dfsSz(u, v);
        sz_[v] += sz_[u];
        if (!heavy_[v] || sz_[u] > sz_[heavy_[v]]) heavy_[v] = u;
    }
}
void dfsHld(int v, int h) {
    head_[v] = h; pos_[v] = cur_++;
    if (heavy_[v]) dfsHld(heavy_[v], h);                 // ciężkie dziecko kontynuuje łańcuch
    for (int u : g[v]) if (u != par_[v] && u != heavy_[v]) dfsHld(u, u);   // lekkie zaczynają nowy
}
// wywołanie: dfsSz(1, 0); dfsHld(1, 1);  poddrzewo v = [pos_[v], pos_[v] + sz_[v] - 1]

