const int N = 200005;
int par_[N], dep_[N], head_[N], pos_[N];
long long query(int l, int r);              // drzewo przedziałowe na pozycjach
long long sumaNaSciezce(int u, int v) {
    long long s = 0;
    while (head_[u] != head_[v]) {
        if (dep_[head_[u]] < dep_[head_[v]]) swap(u, v);
        s += query(pos_[head_[u]], pos_[u]);
        u = par_[head_[u]];
    }
    if (dep_[u] > dep_[v]) swap(u, v);
    return s + query(pos_[u], pos_[v]);
}

// dodawanie x na ścieżce: te same przedziały co przy zapytaniu
const int N = 200005;
int par_[N], dep_[N], head_[N], pos_[N];
void dodajNaPrzedziale(int l, int r, long long x);   // lazy segment tree
void dodajNaSciezce(int u, int v, long long x) {
    while (head_[u] != head_[v]) {
        if (dep_[head_[u]] < dep_[head_[v]]) swap(u, v);
        dodajNaPrzedziale(pos_[head_[u]], pos_[u], x);
        u = par_[head_[u]];
    }
    if (dep_[u] > dep_[v]) swap(u, v);
    dodajNaPrzedziale(pos_[u], pos_[v], x);
}

// pomiar: najwięcej lekkich krawędzi na ścieżce od korzenia w losowym drzewie
int n = 100000;
mt19937 rng(5);
vector<int> p(n + 1, 0), sz(n + 1, 1), heavy(n + 1, 0), light(n + 1, 0);
for (int v = 2; v <= n; v++) p[v] = rng() % (v - 1) + 1;          // p[v] < v
for (int v = n; v >= 2; v--) sz[p[v]] += sz[v];
for (int v = 2; v <= n; v++) if (!heavy[p[v]] || sz[v] > sz[heavy[p[v]]]) heavy[p[v]] = v;
int najwiecej = 0;
for (int v = 2; v <= n; v++) {
    light[v] = light[p[v]] + (heavy[p[v]] != v);                  // lekka krawędź p[v] -> v?
    najwiecej = max(najwiecej, light[v]);
}
cout << (najwiecej <= __lg(n) ? "OK" : "ZLE") << '\n';             // <= log2(n) = 16

const int N = 200005;
int par_[N], dep_[N], head_[N], pos_[N];
long long query(int l, int r);
long long sumaKrawedzi(int u, int v) {
    long long s = 0;
    while (head_[u] != head_[v]) {
        if (dep_[head_[u]] < dep_[head_[v]]) swap(u, v);
        s += query(pos_[head_[u]], pos_[u]);
        u = par_[head_[u]];
    }
    if (dep_[u] > dep_[v]) swap(u, v);
    if (u != v) s += query(pos_[u] + 1, pos_[v]);   // bez LCA
    return s;
}

const int N = 200005;
int pos_[N], sz_[N];
long long query(int l, int r);
long long sumaPoddrzewa(int v) { return query(pos_[v], pos_[v] + sz_[v] - 1); }

const int N = 200005;
int par_[N], dep_[N], head_[N];
int lca(int u, int v) {
    while (head_[u] != head_[v]) {
        if (dep_[head_[u]] < dep_[head_[v]]) swap(u, v);
        u = par_[head_[u]];
    }
    return dep_[u] < dep_[v] ? u : v;
}

auto technika = [](bool aktualizacje, bool maxMin, bool dodawanieNaSciezce) -> string {
    if (dodawanieNaSciezce) return "HLD + lazy segment tree";
    if (!aktualizacje) return maxMin ? "binary lifting z agregatem" : "prefiksy + LCA";
    return maxMin ? "HLD + drzewo przedziałowe" : "Euler tour + Fenwick";
};
cout << technika(false, false, false) << '\n'       // statyczna suma na ścieżce
     << technika(false, true, false) << '\n'        // statyczne max na ścieżce
     << technika(true, false, false) << '\n'        // zmiana wartości + suma
     << technika(true, true, false) << '\n';        // zmiana wartości + max

// pomiar: na ile odcinków łańcuchów rozpada się losowa ścieżka u–v
int n = 100000;
mt19937 rng(9);
vector<int> p(n + 1, 0), sz(n + 1, 1), heavy(n + 1, 0), head(n + 1), dep(n + 1, 0);
for (int v = 2; v <= n; v++) p[v] = rng() % (v - 1) + 1;
for (int v = n; v >= 2; v--) sz[p[v]] += sz[v];
for (int v = 2; v <= n; v++) if (!heavy[p[v]] || sz[v] > sz[heavy[p[v]]]) heavy[p[v]] = v;
head[1] = 1;
for (int v = 2; v <= n; v++) { dep[v] = dep[p[v]] + 1; head[v] = (heavy[p[v]] == v) ? head[p[v]] : v; }
int maxOdc = 0;
for (int it = 0; it < 1000; it++) {
    int u = rng() % n + 1, v = rng() % n + 1, odc = 1;
    while (head[u] != head[v]) {
        if (dep[head[u]] < dep[head[v]]) swap(u, v);
        u = p[head[u]];                 // każdy skok = jedno zapytanie O(log n) do drzewa przedziałowego
        odc++;
    }
    maxOdc = max(maxOdc, odc);
}
cout << (maxOdc <= 2 * __lg(n) + 1 ? "OK" : "ZLE") << '\n';
